class Solution:

	def findTwoElement(self, arr, n):
		unordered_map = {}
		rep = 0
		miss = 0
		for i in arr:
			if i not in unordered_map:
				unordered_map[i] = 1
			else:
				rep = i
		for i in range(1, n + 1):
			if i not in unordered_map:
				miss = i
				return [rep, miss]
